input.sparql:
SELECT ?ts ?point ?name WHERE {
  ?zone a brick:Zone ; rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_mid_ZN_4"))
  ?point ref:hasLocation ?zone ; a brick:AirTemperatureSensor .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?point ?pointClass ?ts WHERE {
  VALUES ?zone {
    http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05
  }
  ?point ref:hasLocation ?zone .
  ?point a ?pointClass .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?point ?pointClass ?ts WHERE {
  ?point ref:hasLocation http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05 .
  ?point a ?pointClass .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?point ?pointClass ?ts ?rel WHERE {
  ?point ref:hasLocation ?zone .
  ?zone rdfs:label ?zl .
  FILTER(CONTAINS(?zl, "Zone_F3_Z05"))
  ?point a ?pointClass .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  OPTIONAL { ?point ref:hasLocation ?rel }
}

SELECT ?point ?ts WHERE {
  ?zone rdfs:label ?zl .
  FILTER(CONTAINS(?zl, "ZN_4"))
  ?zone brick:hasPoint ?point .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}
